insert into public.game_content (game, data, updated_at) values ('price', $seed$[{"name": "霸王茶姬·伯牙绝弦（中杯一杯）", "note": "内地门店约 16-18 元，这杯茶在美国卖 40 元一杯，已经卖出超 6 亿杯", "unit": "一杯", "price": 17, "category": "snack"}, {"name": "蜜雪冰城·冰鲜柠檬水（一杯）", "note": "雪王镇店之宝，十年几乎没涨价，在香港却要卖 9-20 港币", "unit": "一杯", "price": 4, "category": "snack"}, {"name": "蜜雪冰城·新鲜冰淇淋甜筒（一支）", "note": "可能是全国最便宜的现做甜筒，雪王的引流神器", "unit": "一支", "price": 2, "category": "snack"}, {"name": "喜茶·多肉葡萄（标准杯）", "note": "喜茶降价后的主流价位，几年前它还要 29 元", "unit": "一杯", "price": 19, "category": "snack"}, {"name": "瑞幸·生椰拿铁（用券后一杯）", "note": "9.9 元咖啡大战的代表作，原价其实是 29 元左右", "unit": "一杯", "price": 9.9, "category": "snack"}, {"name": "农夫山泉矿泉水（550ml 一瓶）", "note": "「我们不生产水，我们只是大自然的搬运工」，便利店常见价", "unit": "一瓶", "price": 2, "category": "snack"}, {"name": "可口可乐（330ml 罐装一听）", "note": "超市常见价，可乐被称为「快乐水」，配方保密超过 100 年", "unit": "一听", "price": 3, "category": "snack"}, {"name": "旺仔牛奶（245ml 一罐）", "note": "超市常见价，「三年六班的李子明同学」的妈妈送来的就是它", "unit": "一罐", "price": 5, "category": "snack"}, {"name": "卫龙大面筋辣条（106g 一袋）", "note": "电商常见价，辣条界的「爱马仕」，卫龙已经是上市公司", "unit": "一袋", "price": 5.5, "category": "snack"}, {"name": "乐事薯片原味（135g 大袋装）", "note": "超市常见价，袋子里一半是氮气，是为了保护薯片不碎", "unit": "一袋", "price": 8.5, "category": "snack"}, {"name": "奥利奥原味夹心饼干（97g 一盒）", "note": "超市常见价，「扭一扭、舔一舔、泡一泡」", "unit": "一盒", "price": 6.5, "category": "snack"}, {"name": "好丽友·派（6 枚装一盒）", "note": "超市常见价，「好丽友，好朋友」，经典巧克力派", "unit": "一盒", "price": 9.9, "category": "snack"}, {"name": "元气森林白桃气泡水（480ml 一瓶）", "note": "便利店常见价，靠「0 糖 0 脂 0 卡」火遍全国", "unit": "一瓶", "price": 5.5, "category": "snack"}, {"name": "三只松鼠每日坚果（750g/30 小包一箱）", "note": "电商大促常见价，平均一小包 3 块钱", "unit": "一箱", "price": 89, "category": "snack"}, {"name": "星巴克大杯拿铁（一杯）", "note": "门店标准价，约等于 3 杯多瑞幸券后价", "unit": "一杯", "price": 33, "category": "snack"}, {"name": "东方树叶乌龙茶（900ml 大瓶装）", "note": "便利店常见价，曾被评为「最难喝饮料」之一，后来逆袭成无糖茶之王", "unit": "一瓶", "price": 6, "category": "snack"}, {"name": "安慕希希腊风味酸奶（205g×10 瓶一箱）", "note": "超市常见价，走亲访友送礼界的「硬通货」", "unit": "一箱", "price": 45, "category": "snack"}, {"name": "哈根达斯单球冰淇淋（门店一球）", "note": "门店标准价，「爱她就请她吃哈根达斯」，一球顶 19 个蜜雪甜筒", "unit": "一球", "price": 38, "category": "snack"}, {"name": "卡游奥特曼卡片普通包（一包 8 张）", "note": "小卖部标准价，全国小学生的「社交货币」，稀有卡在二手市场能炒到上万", "unit": "一包", "price": 2, "category": "toy"}, {"name": "卡游奥特曼卡片星云版（一整盒）", "note": "常卖价 49.9 元，开出 GP 卡的概率让无数小学生「上头」", "unit": "一盒", "price": 50, "category": "toy"}, {"name": "泡泡玛特 mini Labubu 盲盒（一个）", "note": "2025 年官方发售价，整套 14 个要 1106 元，曾经一盒难求", "unit": "一个", "price": 79, "category": "toy"}, {"name": "Labubu 3.0 搪胶毛绒盲盒（一个）", "note": "官方发售价，隐藏款在二手市场曾被炒到上千元，全球明星都在背", "unit": "一个", "price": 99, "category": "toy"}, {"name": "泡泡玛特马年限定盲盒「马力全开」（一个）", "note": "2026 年 1 月发售，上线秒售罄，端盒 1113 元", "unit": "一个", "price": 159, "category": "toy"}, {"name": "乐高经典创意大号积木盒（790 粒装）", "note": "官方价，乐高名字来自丹麦语「玩得好」（Leg Godt）", "unit": "一盒", "price": 299, "category": "toy"}, {"name": "乐高保时捷 911 跑车套装（10295，1458 粒）", "note": "官方发售价，拼完可以同时变成 Turbo 和 Targa 两种车型", "unit": "一盒", "price": 1649, "category": "toy"}, {"name": "晨光中性笔（0.5mm 一支）", "note": "文具店标准价，全国学生一年要用掉几十亿支", "unit": "一支", "price": 2, "category": "toy"}, {"name": "得力修正带（12m 一个）", "note": "文具店常见价，写错字星人的救星", "unit": "一个", "price": 5, "category": "toy"}, {"name": "国产正版动漫吧唧徽章（一个）", "note": "谷子店常见价 15-25 元，限量「海景谷」二手能炒到几百上千元", "unit": "一个", "price": 20, "category": "toy"}, {"name": "二次元痛包（装吧唧的透明包，一个）", "note": "电商常见价，包是基础款，里面别满吧唧后总价可能上千", "unit": "一个", "price": 80, "category": "toy"}, {"name": "名创优品盲盒公仔（一个）", "note": "门店常见价，平价盲盒代表，泡泡玛特的「平替」", "unit": "一个", "price": 29.9, "category": "toy"}, {"name": "三丽鸥库洛米毛绒挂件（正版小号）", "note": "专柜常见价，库洛米是「酷洛米」星人，My Melody 的死对头", "unit": "一个", "price": 59, "category": "toy"}, {"name": "三阶魔方（普通竞速款一个）", "note": "电商常见价，世界纪录保持者复原一个只要 3 秒多", "unit": "一个", "price": 15, "category": "toy"}, {"name": "专业竞技悠悠球（一个）", "note": "电商常见价，《火力少年王》同款情怀，爸妈小时候也玩过", "unit": "一个", "price": 35, "category": "toy"}, {"name": "小学生护脊减负书包（一个）", "note": "电商主流价位 150-300 元，比很多成人双肩包还贵", "unit": "一个", "price": 200, "cat