insert into public.game_content (game, data, updated_at) values ('shiliu-chinese', $seed$[{"why": "单韵母一共有六个：a o e i u ü，要会读会背哦。b p m f 那些是声母，ai ei 那些是复韵母，不是单韵母。", "right": "a o e i u ü", "title": "六个单韵母", "topic": "拼音", "prompt": "小朋友，拼音里的六个单韵母是哪一组呀？", "wrongs": ["b p m f d t", "ai ei ui ao"]}, {"why": "b（玻）是声母，要和韵母拼在一起才好读。a 和 o 都是单韵母，自己就能读出来。", "right": "b", "title": "声母里的双胞胎", "topic": "拼音", "prompt": "下面哪个是声母，不是韵母呢？", "wrongs": ["a", "o"]}, {"why": "一声的帽子是平平的一横“ˉ”，读起来又高又平，像 mā（妈）。二声是往上扬，四声是往下降。", "right": "第一声", "title": "一声怎么读", "topic": "拼音", "prompt": "ā 这个音上面是一横，它是第几声呀？", "wrongs": ["第二声", "第四声"]}, {"why": "二声“ˊ”像往上爬的小坡，声音往上扬，像问“啊？”。三声是先降后升的“ˇ”，不一样哦。", "right": "第二声", "title": "声调小帽子", "topic": "拼音", "prompt": "“á”上面的帽子是斜着往上的，它读第几声？", "wrongs": ["第一声", "第三声"]}, {"why": "声母 b 加韵母 ā，前音轻短后音重，连起来就是 bā（八）。前面换成 p 就读 pā 啦。", "right": "bā", "title": "拼一拼读出来", "topic": "拼音", "prompt": "b 和 ā 拼在一起，读什么呀？", "wrongs": ["pā", "dā"]}, {"why": "ü 碰到 j q x 就要脱帽子去掉两点，比如 jú（橘）。但读的时候还是读 ü 的音哦。", "right": "去掉两点写成 u", "title": "小ü要脱帽", "topic": "拼音", "prompt": "j 和 ü 拼在一起的时候，ü 上面的两点要怎么样？", "wrongs": ["两点不动", "换成 i"]}, {"why": "这是三拼音节：声母 g、介母 u、韵母 a，连读成 guā（瓜）。读的时候要又快又顺溜。", "right": "guā", "title": "三拼音节", "topic": "拼音", "prompt": "g–u–ā 三个音拼起来，读什么呀？", "wrongs": ["gā", "kuā"]}, {"why": "zhi 是整体认读音节，看一眼就直接读出来，不用一个一个拼。ba、mo 是要拼读的哦。", "right": "zhi", "title": "整体认读音节", "topic": "拼音", "prompt": "下面哪个是要“整体认读”的音节，不用拼？", "wrongs": ["ba", "mo"]}, {"why": "“日”就是太阳，古时候人们照着圆圆的太阳画出来的。月亮是“月”，弯弯的。", "right": "太阳", "title": "“日”是什么意思", "topic": "识字", "prompt": "“日”这个字，画的是天上的什么呀？", "wrongs": ["月亮", "星星"]}, {"why": "“月”是月亮，弯弯的像小船。白天的太阳是“日”，是圆圆的。", "right": "月", "title": "“月”像什么", "topic": "识字", "prompt": "弯弯的、晚上天上挂着的，是哪个字呀？", "wrongs": ["日", "云"]}, {"why": "太阳和月亮都很亮，合起来就是“明”，亮堂堂的意思，像“明亮”。", "right": "明", "title": "日月合起来", "topic": "识字", "prompt": "“日”和“月”合在一起，组成哪个字呀？", "wrongs": ["朋", "阳"]}, {"why": "一棵树是“木”，两棵树并排就是“林”（树林）。三个木叠起来才是“森”，树更多啦。", "right": "林", "title": "两个木变成林", "topic": "识字", "prompt": "两个“木”并排放在一起，是哪个字呀？", "wrongs": ["森", "本"]}, {"why": "人多力量大，三个人就是“众”（很多人）。两个人一前一后是“从”，跟着走的意思。", "right": "众", "title": "三个人变成众", "topic": "识字", "prompt": "三个“人”叠在一起，是哪个字？", "wrongs": ["从", "坐"]}, {"why": "“火”就是烧起来的火苗，红红的、暖暖的。它和“水”是好朋友，常常一起学。", "right": "火苗", "title": "“火”的样子", "topic": "识字", "prompt": "一年级学的“火”字，画的是什么在烧呀？", "wrongs": ["水波", "小草"]}, {"why": "这三个字都和水有关，所以都有“氵”三点水。草字头是“艹”，长在草上的字才用。", "right": "三点水", "title": "认一认偏旁", "topic": "识字", "prompt": "“江、河、海”这三个字，都有哪个偏旁呀？", "wrongs": ["草字头", "木字旁"]}, {"why": "“花”上面是“艹”草字头，因为花是植物。河有三点水（和水有关），明有日和月。", "right": "花", "title": "草字头的字", "topic": "识字", "prompt": "下面哪个字是“草字头”，和植物有关？", "wrongs": ["河", "明"]}, {"why": "这些字都和树木有关，所以都带“木”。古时候的桥也常用木头做，所以也有木字旁。", "right": "木字旁", "title": "木字旁一家", "topic": "识字", "prompt": "“树、林、桥”都有哪个偏旁呢？", "wrongs": ["三点水", "提手旁"]}, {"why": "写字有规矩：先横后竖。写“十”要先画一横“一”，再画一竖“丨”，这样才好看。", "right": "先写横", "title": "先写哪一笔", "topic": "识字", "prompt": "写“十”字的时候，应该先写哪一笔呀？", "wrongs": ["先写竖", "一起写"]}, {"why": "写字要从上到下。“三”是三横，先写最上面那一横，再中间，最后下面，整整齐齐。", "right": "从上到下，一横一横写", "title": "从上到下写", "topic": "识字", "prompt": "写“三”这个字，正确的顺序是怎样的？", "wrongs": ["从下往上写", "从中间开始写"]}, {"why": "写带框框的字要“先里头后关门”。“回”先写外框上面和里面的小口，最后再写底下那一横把门关上。", "right": "先里面，最后封口", "title": "先里头还是先关门", "topic": "识字", "prompt": "写“回”字，先写里面的小口，还是先把外面封口？", "wrongs": ["先把外面全写完", "从下往上写"]}, {"why": "“一”就是横平平的一笔，所以是一画，最简单啦。“二”是两画，“三”是三画。", "right": "一画", "title": "“一”有几画", "topic": "识字", "prompt": "“一”这个字，一共有几画呀？", "wrongs": ["两画", "三画"]}, {"why": "“水”是能喝的，所以“喝水”对。火不能喝，山也不能喝，那两个不通顺哦。", "right": "喝水", "title": "给“水”找朋友", "topic": "组词", "prompt": "“水”可以组成下面哪个词呀？", "wrongs": ["喝火", "喝山"]}, {"why": "“大象”是又高又大的动物，用“大”正好。蚂蚁那么小，说“大蚂蚁”就不太对啦。", "right": "大象", "title": "“大”能组什么", "topic": "组词", "prompt": "用“大”组词，下面哪个最合适？", "wrongs": ["小象", "大蚂蚁"]}, {"why": "小朋友每天去学校叫“上学”，回家叫“放学”。“上水、下学”都不是常用的词哦。", "right": "上学", "title": "“上”的词", "topic": "组词", "prompt": "“上”可以组成哪个词呀？", "wrongs": ["下学", "上水"]}, {"why": "我们有一双“小手”，可以画画、吃饭。脚是“小脚”，鼻子是“鼻子”，不能乱拼在一起。", "right": "小手", "title": "“手”的词语", "topic": "组词", "prompt": "用“手”组词，下面哪个对？", "wrongs": ["小脚手", "手鼻"]}, {"why": "蓝蓝的、在头顶上的叫“天空”。后面两个字凑在一起读不通，不是词哦。", "right": "天空", "title": "“天”组词", "topic": "组词", "prompt": "“天”能组成下面哪个词？", "wrongs": ["天地手", "空天天"]}, {"why": "大和小是一对反义词，意思正好相反，像大象很大、蚂蚁很小。多的反义词是“少”哦。", "right": "小", "title": "“大”的反义词", "topic": "反义词", "prompt": "“大”的反义词是什么呀？", "wrongs": ["多", "高"]}, {"why": "上和下是一对，往天上是“上”，往地下是“下”。左和右、前和后是别的对子。", "right": "下", "title": "“上”反过来", "topic": "反义词", "prompt": "“上”的反义词是哪个字？", "wrongs": ["左", "前"]}, {"why": "东西很多是“多”，没几个是“少”，它俩正好相反。大的反义词是“小”，别记错啦。", "right": "少", "title": "“多”和谁相反", "topic": "反义词", "prompt": "“多”的反义词是什么？", "wrongs": ["大", "高"]}, {"why": "长长的反过来就是“短短的”，像长尾巴和短尾巴。高的反义词是“矮”哦。", "right": "短", "title": "“长”反过来", "topic": "反义词", "prompt": "“长”的反义词是哪一个？", "wrongs": ["高", "大"]}, {"why": "黑和白是一对，乌黑的夜晚和雪白的雪。红和灰是颜色，但不是“黑”的反义词。", "right": "白", "title": "“黑”的反义词", "topic": "反义词", "prompt": "“黑”的反义词是什么呀？", "wrongs": ["红", "灰"]}, {"why": "开门和关门是一对反义词。把门打开是“开”，把门合上是“关”。", "right": "关", "title": "“开”反过来", "topic": "反义词", "prompt": "门“开”了，反过来就是门怎么样？", "wrongs": ["走", "动"]}, {"why": "朝我这边是“来”，离开我这边是“去”，正好相反，像“来来去去”。", "right": "去", "title": "“来”和谁相反", "topic": "反义词", "prompt": "“来”的反义词是哪个字？", "wrongs": ["到", "走"]}, {"why": "跑得很快和走得很慢，快和慢是一对反义词，意思相反哦。", "right": "慢", "title": "“快”反过来", "topic": "反义词", "prompt": "“快”的反义词是什么呢？", "wrongs": ["停", "走"]}, {"why": "个子高高的反过来是“矮矮的”，高和矮是一对。大的反义词是“小”，要分清楚。", "right": "矮", "title": "“高”的反义词", "topic": "反义词", "prompt": "“高”的反义词是哪个字？", "wrongs": ["大", "长"]}, {"why": "高兴和快乐都是开开心心的意思，是近义词。难过和生气是不开心，意思反过来啦。", "right": "快乐", "title": "和“高兴”差不多", "topic": "近义词", "prompt": "哪个词和“高兴”的意思差不多呀？", "wrongs": ["难过", "生气"]}, {"why": "漂亮就是好看、美美的，它俩是近义词。难看是不好看，意思正好相反。", "right": "好看", "title": "和“漂亮”一样美", "topic": "近义词", "prompt": "哪个词和“漂亮”意思差不多？", "wrongs": ["难看", "害怕"]}, {"why": "大大的牛要用“头”：一头牛。小动物像小鸟用“只”，长长的鱼、虫用“条”。", "right": "头", "title": "一( )牛", "topic": "量词", "prompt": "一_____牛，括号里填哪个字最好？", "wrongs": ["只", "条"]}, {"why": "花儿要用“朵”：一朵花、一朵云。牛用“头”，鱼用“条”，每样东西都有自己的量词。", "right": "朵", "title": "一( )花", "topic": "量词", "prompt": "一_____花，应该填什么量词？", "wrongs": ["头", "条"]}, {"why": "鱼是长长的，要用“条”：一条鱼、一条河、一条路。花用“朵”，牛用“头”。", "right": "条", "title": "一( )鱼", "topic": "量词", "prompt": "一_____鱼，括号里填哪个对呀？", "wrongs": ["头", "朵"]}, {"why": "小鸟、小猫这样的小动物用“只”：一只鸟、一只猫。书才用“本”，一本书。", "right": "只", "title": "一( )鸟", "topic": "量词", "prompt": "天上飞着一_____鸟，填什么字？", "wrongs": ["头", "本"]}, {"why": "书要用“本”：一本书、一本作业。“只”是给小动物用的，“条”是给长长的东西用的。", "right": "本", "title": "一( )书", "topic": "量词", "prompt": "我有一_____书，括号里填哪个量词？", "wrongs": ["只", "条"]}, {"why": "树和小草要用“棵”：一棵树、一棵草。这个“棵”有木字旁，正好和树有关。", "right": "棵", "title": "一( )树", "topic": "量词", "prompt": "院子里有一_____树，填什么字好呢？", "wrongs": ["只", "头"]}, {"why": "汽车、自行车要用“辆”：一辆车。这个“辆”有车字旁，专门给车用的。", "right": "辆", "title": "一( )车", "topic": "量词", "prompt": "马路上开过一_____车，括号里填什么？", "wrongs": ["只", "朵"]}, {"why": "又大又稳的桥、山、房子要用“座”：一座桥、一座山。这样听起来稳稳当当的。", "right": "座", "title": "一( )桥", "topic": "量词", "prompt": "河上有一_____桥，应该填哪个量词？", "wrongs": ["条", "只"]}, {"why": "平平常常把一件事说完，结尾用句号“。”。问问题才用问号，很激动才用感叹号。", "right": "句号。", "title": "句末点什么", "topic": "句子", "prompt": "“我去上学。”这句话说完了，末尾要点什么标点？", "wrongs": ["问号？", "感叹号！"]}, {"why": "问别人问题，句子末尾要用问号“？”。逗号是句子中间停一下用的，不放在最后。", "right": "问号？", "title": "问句用什么号", "topic": "句子", "prompt": "“你叫什么名字”这句是在问问题，末尾要用哪个标点？", "wrongs": ["句号。", "逗号，"]}, {"why": "又惊又喜、很激动的时候，末尾用感叹号“！”，像在大声喊出来。", "right": "感叹号！", "title": "激动用什么号", "topic": "句子", "prompt": "“今天真高兴”，说得特别开心特别激动，末尾用哪个标点？", "wrongs": ["句号。", "问号？"]}, {"why": "一句话常常是：谁 + 做什么。先说“我”（谁），再说“去上学”（做什么），就通顺啦。", "right": "我去上学", "title": "把句子排好", "topic": "句子", "prompt": "“上学 我 去”，排成通顺的话应该是哪句？", "wrongs": ["上学去我", "去我上学"]}, {"why": "天上有白云、有太阳。小鱼在水里游，桌子放在屋里，它们不在天上哦。", "right": "白云", "title": "补全小句子", "topic": "句子", "prompt": "“天上有____。”填哪个最通顺呀？", "wrongs": ["小鱼", "桌子"]}, {"why": "小鸟有翅膀，在天上是“飞”。鱼在水里“游”，人在地上“跑”，要选对动作。", "right": "飞", "title": "谁在做什么", "topic": "句子", "prompt": "“小鸟在天上____。”填哪个词最合适？", "wrongs": ["游", "跑"]}, {"why": "话没说完、停一下喘口气，就用逗号“，”。等整句话都说完了，才用句号“。”。", "right": "逗号，", "title": "逗号在哪歇", "topic": "句子", "prompt": "一句话还没说完、要中间歇一口气，用哪个标点呀？", "wrongs": ["句号。", "问号？"]}, {"why": "《咏鹅》是唐朝的骆宾王小时候写的，那时候他才七岁，和你差不多大呢！", "right": "骆宾王", "title": "《咏鹅》是谁写的", "topic": "古诗", "prompt": "“鹅，鹅，鹅”这首《咏鹅》是哪位诗人写的呀？", "wrongs": ["李白", "王维"]}, {"why": "《咏鹅》开头是“鹅，鹅，鹅，曲项向天歌”，说大白鹅弯着脖子朝天唱歌呢。", "right": "曲项向天歌", "title": "咏鹅下一句", "topic": "古诗", "prompt": "“鹅，鹅，鹅，”下一句是什么呀？", "wrongs": ["白毛浮绿水", "红掌拨清波"]}, {"why": "原句是“白毛浮绿水，红掌拨清波”。白白的羽毛浮在绿绿的水上，红红的脚掌划着清清的水。", "right": "绿水", "title": "白毛浮在哪", "topic": "古诗", "prompt": "《咏鹅》里“白毛浮____”，鹅的白毛浮在什么上面？", "wrongs": ["蓝天", "青草"]}, {"why": "《静夜思》是唐朝大诗人李白写的，他看着月亮想起了远方的家。", "right": "李白", "title": "《静夜思》谁写的", "topic": "古诗", "prompt": "“床前明月光”这首《静夜思》是哪位大诗人写的？", "wrongs": ["杜甫", "骆宾王"]}, {"why": "《静夜思》是：床前明月光，疑是地上霜。月光白白的洒在地上，李白还以为是霜呢。", "right": "疑是地上霜", "title": "静夜思第二句", "topic": "古诗", "prompt": "“床前明月光，”下一句是什么呀？", "wrongs": ["低头思故乡", "举头望明月"]}, {"why": "最后一句是“低头思故乡”。看着月亮，李白低下头，想念自己的家乡了。", "right": "故乡", "title": "低头想什么", "topic": "古诗", "prompt": "《静夜思》最后“低头思____”，李白低头在想什么？", "wrongs": ["月亮", "朋友"]}, {"why": "《画》是唐朝王维写的。这首诗其实在说一幅画：画里的山有颜色，水却没声音。", "right": "王维", "title": "《画》是谁的诗", "topic": "古诗", "prompt": "“远看山有色，近听水无声”这首《画》是谁写的？", "wrongs": ["李白", "李绅"]}, {"why": "原句是“近听水无声”。因为是画出来的水，走近了听也没有一点声音，很有趣吧。", "right": "无声", "title": "画里的水", "topic": "古诗", "prompt": "《画》里说“近听水____”，走近听画里的水有没有声音？", "wrongs": ["有声", "很响"]}, {"why": "农民大中午顶着太阳干活，汗水滴进土里。所以“粒粒皆辛苦”，我们吃饭不能浪费哦。", "right": "粮食来得很辛苦，要珍惜", "title": "《悯农》讲什么", "topic": "古诗", "prompt": "“锄禾日当午，汗滴禾下土”这首《悯农》在告诉我们什么？", "wrongs": ["种花很好玩", "中午要睡觉"]}, {"why": "“谁知盘中餐，粒粒皆辛苦”——碗里每一粒米饭，都是农民辛辛苦苦种出来的。", "right": "粒粒皆辛苦", "title": "盘中餐辛苦", "topic": "古诗", "prompt": "《悯农》里“谁知盘中餐，____”，下一句是什么？", "wrongs": ["夜来风雨声", "汗滴禾下土"]}, {"why": "“小时不识月，呼作白玉盘”——李白说小时候不认识月亮，把它叫成白白的玉盘子，真可爱。", "right": "呼作白玉盘", "title": "《古朗月行》开头", "topic": "古诗", "prompt": "李白《古朗月行》开头“小时不识月，”下一句是什么？", "wrongs": ["疑是地上霜", "低头思故乡"]}, {"why": "春天太舒服了，睡得可香了，不知不觉天就亮了。下一句是“处处闻啼鸟”，到处听见鸟叫。", "right": "睡得香，不知不觉天亮了", "title": "《春晓》睡到啥时候", "topic": "古诗", "prompt": "《春晓》“春眠不觉晓”，是说春天睡觉怎么样啦？", "wrongs": ["一夜没睡着", "很早就醒了"]}, {"why": "《小池》是宋朝杨万里写的。小小的荷叶刚冒出尖尖的角，就有蜻蜓站上去啦。", "right": "杨万里", "title": "《小池》谁写的", "topic": "古诗", "prompt": "“小荷才露尖尖角”出自《小池》，是哪位诗人写的？", "wrongs": ["李白", "王维"]}, {"why": "“偷采白莲回”——小孩划着小船去采白白的莲蓬，开心地回来了。这是白居易写的。", "right": "白莲", "title": "《池上》偷采啥", "topic": "古诗", "prompt": "《池上》里“小娃撑小艇，偷采____回”，小孩偷采的是什么？", "wrongs": ["苹果", "小鱼"]}, {"why": "下雨要打“雨伞”才不会淋湿。扇子是热的时候扇风用的，手电筒是天黑照明用的。", "right": "雨伞", "title": "下雨打什么", "topic": "理解", "prompt": "下雨的时候，出门要带什么挡雨呀？", "wrongs": ["扇子", "手电筒"]}, {"why": "冬天冷，天上飘下白白的“雪”，可以堆雪人。花在春天开，叶子秋天才会落。", "right": "雪", "title": "冬天会下啥", "topic": "理解", "prompt": "很冷很冷的冬天，天上会飘下白白的什么？", "wrongs": ["花", "叶"]}, {"why": "小鸡是母鸡妈妈生的蛋孵出来的，所以妈妈是“母鸡”。小鸭的妈妈才是鸭子哦。", "right": "母鸡", "title": "小鸡的妈妈", "topic": "理解", "prompt": "毛茸茸的小鸡，它的妈妈是谁呀？", "wrongs": ["小鸭", "小猫"]}, {"why": "太阳早上从东边升起，天就亮了；傍晚从西边落下，天就黑了。半夜是看不见太阳的。", "right": "早上", "title": "太阳什么时候出来", "topic": "理解", "prompt": "红红的太阳一般是什么时候从东边升起来呀？", "wrongs": ["半夜", "晚上"]}, {"why": "ai 是复韵母，由 a 和 i 两个字母合成，要一口气连着读。a 是单韵母，b 是声母哦。", "right": "ai", "title": "复韵母认一认", "topic": "拼音", "prompt": "下面哪一个是复韵母，是两个字母合在一起的？", "wrongs": ["a", "b"]}, {"why": "三声的帽子“ˇ”像个小山谷，先往下再往上，读起来拐个弯，像 mǎ（马）。", "right": "第三声", "title": "三声怎么读", "topic": "拼音", "prompt": "“ǎ”上面的帽子是先弯下去再翘上来，它读第几声？", "wrongs": ["第一声", "第二声"]}, {"why": "四声“ˋ”像往下滑的小滑梯，声音一下子降下来，又快又重，像 bà（爸）。", "right": "第四声", "title": "四声往下降", "topic": "拼音", "prompt": "“à”上面的帽子是斜着往下的，它读第几声？", "wrongs": ["第二声", "第三声"]}, {"why": "yi 是整体认读音节，不用拼，一看就读出来。li、di 要把声母和韵母拼在一起读哦。", "right": "yi", "title": "大y带小i", "topic": "拼音", "prompt": "下面哪个是整体认读音节，看一眼就直接读出来？", "wrongs": ["li", "di"]}, {"why": "声母 m 加韵母 ā，连起来读 mā（妈）。前面换成 n 就读 nā，韵母换成 ō 就读 mō 啦。", "right": "mā", "title": "换个声母读", "topic": "拼音", "prompt": "m 和 ā 拼在一起，读什么呀？", "wrongs": ["mō", "nā"]}, {"why": "ü 碰到 j q x 都要脱帽去掉两点，所以 q 加 ü 写成 qu，比如 qù（去）。读还是读 ü 的音。", "right": "去掉两点写成 u", "title": "qu也要脱帽", "topic": "拼音", "prompt": "q 和 ü 拼在一起的时候，ü 上面的两点要怎么样？", "wrongs": ["两点留着", "换成 o"]}, {"why": "这是三拼音节：声母 h、介母 u、韵母 a，又快又顺地连起来读 huā（花）。", "right": "huā", "title": "三拼读花朵", "topic": "拼音", "prompt": "h–u–ā 三个音拼起来，读什么呀？", "wrongs": ["hā", "huɑ"]}, {"why": "an 读完舌尖会顶住上牙床，是前鼻韵母，像 shān（山）。后鼻音 ang 是从鼻子后面出来的。", "right": "前鼻韵母", "title": "前鼻音an", "topic": "拼音", "prompt": "“an”是把舌头顶住上面读出来的，它叫什么韵母？", "wrongs": ["单韵母", "声母"]}, {"why": "打、拍、拉左边都是“扌”提手旁，多和手的动作有关。三点水的字大多和水有关哦。", "right": "提手旁", "title": "提手旁的字", "topic": "识字", "prompt": "“打、拍、拉”这些字，旁边都有同一个偏旁，是哪个？", "wrongs": ["三点水", "木字旁"]}, {"why": "吃、叫、吹左边都是“口”，因为这些事都要用到嘴巴。口字旁的字很多和嘴有关。", "right": "口字旁", "title": "口字旁一家", "topic": "识字", "prompt": "“吃、叫、吹”这几个字，左边都有哪个偏旁？", "wrongs": ["日字旁", "草字头"]}, {"why": "“休”就是一个人靠着树木歇一歇，所以是休息的休。两个木才是“林”哦。", "right": "休", "title": "人靠树休息", "topic": "识字", "prompt": "一个“人”加一个“木”，合起来是什么字？", "wrongs": ["体", "林"]}, {"why": "“目”就是眼睛，画的是一只眼。“月”是天上的月亮，“日”是太阳，要分清楚。", "right": "目", "title": "日月一起亮", "topic": "识字", "prompt": "左边“目”、右边“月”，这两个字哪个和眼睛有关？", "wrongs": ["月", "日"]}, {"why": "一个木是“木”，两个木是“林”，三个木就是“森”，树很多很多就成了森林。", "right": "森", "title": "三木变森林", "topic": "识字", "prompt": "三个“木”叠在一起，是哪个字呀？", "wrongs": ["林", "木"]}, {"why": "写“十”要“先横后竖”：先写一横，再写一竖。这是写字的好习惯，很多字都这样。", "right": "先写横", "title": "先横还是先竖", "topic": "识字", "prompt": "写“十”字的时候，应该先写哪一笔？", "wrongs": ["先写竖", "都一样"]}, {"why": "“中”字先写口字框，最后再写中间贯穿的一竖。竖在最后写，字才站得稳稳的。", "right": "最后写", "title": "中字竖最后", "topic": "识字", "prompt": "写“中”字的时候，中间那一长竖一般什么时候写？", "wrongs": ["第一笔写", "不用写"]}, {"why": "“高山”是又高又大的山，是常用词。我们说水很深、云很白，但一般不说“高水、高云”。", "right": "高山", "title": "给“山”组词", "topic": "组词", "prompt": "下面哪个词里有“山”字，是真的词语？", "wrongs": ["高水", "高云"]}, {"why": "“火车”是会跑的长长的车，是常用词。火和鱼、火和树一般不会组在一起做词哦。", "right": "火车", "title": "“火”能组什么", "topic": "组词", "prompt": "下面哪个词里有“火”字，意思也对？", "wrongs": ["火鱼", "火树"]}, {"why": "“开口”就是张开嘴说话或吃东西。我们说“开口说话”，用的就是嘴巴这个“口”。", "right": "开口", "title": "“口”的词语", "topic": "组词", "prompt": "“张开嘴巴”里的嘴，可以用哪个带“口”的词？", "wrongs": ["开手", "开眼"]}, {"why": "天上的云是白白的，所以叫“白云”。草和叶子大多是绿色的，不说“白草、白叶”哦。", "right": "白云", "title": "“白”组个词", "topic": "组词", "prompt": "下面哪个词里有“白”字，颜色是对的？", "wrongs": ["白草", "白叶"]}, {"why": "走在最前面是“前”，跟在最后面是“后”，它们正好相反。前和后是一对好朋友。", "right": "后", "title": "“前”反过来", "topic": "反义词", "prompt": "“前”的反义词是哪个字？", "wrongs": ["左", "上"]}, {"why": "离得很远是“远”，离得很近是“近”。比如月亮很远，桌子很近，它们正好相反。", "right": "近", "title": "“远”反过来", "topic": "反义词", "prompt": "“远”和哪个字的意思相反？", "wrongs": ["高", "大"]}, {"why": "从屋里到外面是“出”，从外面到屋里是“入”。出去和进来正好相反哦。", "right": "入", "title": "“出”反过来", "topic": "反义词", "prompt": "“出门”的“出”，反义词是哪个字？", "wrongs": ["关", "走"]}, {"why": "天刚亮起得早是“早”，太阳落山天黑了是“晚”。早和晚，一个开头一个结尾。", "right": "晚", "title": "“早”反过来", "topic": "反义词", "prompt": "“早上”的“早”，反义词是哪个字？", "wrongs": ["快", "冷"]}, {"why": "我们有左手和右手，左和右正好分在两边，是一对反义词。", "right": "右", "title": "“左”反过来", "topic": "反义词", "prompt": "“左手”的“左”，反义词是哪个字？", "wrongs": ["上", "前"]}, {"why": "“着急”和“焦急”都是心里很急、等不及的样子，意思差不多。开心是高兴，不一样哦。", "right": "焦急", "title": "和“着急”差不多", "topic": "近义词", "prompt": "“着急”和下面哪个词意思最接近？", "wrongs": ["开心", "安静"]}, {"why": "“喜欢”和“爱”都是心里觉得好、很想亲近，意思很接近。怕和气都是别的心情。", "right": "爱", "title": "和“喜欢”差不多", "topic": "近义词", "prompt": "“喜欢”和下面哪个词意思最接近？", "wrongs": ["怕", "气"]}, {"why": "“美丽”和“漂亮”都是说东西好看，意思差不多。难看正好相反，不能选。", "right": "漂亮", "title": "和“美丽”差不多", "topic": "近义词", "prompt": "“美丽的花”里的“美丽”，和哪个词意思接近？", "wrongs": ["难看", "矮小"]}, {"why": "“明白”和“懂”都是心里搞清楚了、知道了，意思差不多。忘是记不住，不一样哦。", "right": "懂", "title": "和“明白”差不多", "topic": "近义词", "prompt": "“我明白了”里的“明白”，和哪个词意思接近？", "wrongs": ["忘", "哭"]}, {"why": "苹果圆圆的，用“一个苹果”。条用来数鱼、河，只用来数小动物，不配苹果哦。", "right": "个", "title": "一( )苹果", "topic": "量词", "prompt": "“一____苹果”，中间填哪个量词最好？", "wrongs": ["条", "只"]}, {"why": "筷子要两根才好夹菜，所以用“一双筷子”。鞋子、手套也是“一双”，因为都成对。", "right": "双", "title": "一( )筷子", "topic": "量词", "prompt": "吃饭用的筷子是两根一起的，“一____筷子”填哪个？", "wrongs": ["个", "本"]}, {"why": "有把手能拿在手里的东西常用“把”，比如一把伞、一把椅子。头用来数牛，朵用来数花。", "right": "把", "title": "一( )雨伞", "topic": "量词", "prompt": "挡雨的雨伞，“一____雨伞”填哪个量词？", "wrongs": ["头", "朵"]}, {"why": "上身穿的衣服用“一件”。裤子、裙子那种长长的才用“一条”，桥和山才用“一座”。", "right": "件", "title": "一( )衣服", "topic": "量词", "prompt": "“一____衣服”，中间填哪个量词最合适？", "wrongs": ["条", "座"]}, {"why": "很多动物聚在一起用“群”，比如一群小鸟、一群羊。座用来数桥、山，不能数小鸟。", "right": "一群小鸟", "title": "一( )小鸟", "topic": "量词", "prompt": "天上飞着好多小鸟，一大堆该用哪个词？", "wrongs": ["一座小鸟", "一把小鸟"]}, {"why": "早上太阳从东边“升”起来，天就亮了。傍晚才是“落”下去，太阳不会自己“飞”哦。", "right": "升", "title": "太阳怎么样", "topic": "句子", "prompt": "“红红的太阳____起来了。”填哪个词最合适？", "wrongs": ["落", "飞"]}, {"why": "一句话要先说谁（我），再说做什么（爱吃），最后说东西（苹果），就是“我爱吃苹果”。", "right": "我爱吃苹果", "title": "把词排成句", "topic": "句子", "prompt": "把“吃 我 苹果 爱”排成一句通顺的话，是哪句？", "wrongs": ["苹果吃我爱", "爱苹果我吃"]}, {"why": "心里很开心、很激动地夸一句，末尾用感叹号“！”。普通说完一句话才用句号“。”。", "right": "感叹号！", "title": "夸一夸用啥号", "topic": "句子", "prompt": "“今天的天气真好啊___”句子末尾该用什么标点？", "wrongs": ["句号。", "问号？"]}, {"why": "形容花的样子可以说“红红的花”“美丽的花”。花不会“飞来飞去”，那是描述别的东西的。", "right": "红红", "title": "什么样的花", "topic": "句子", "prompt": "“花园里开满了____的花。”填哪个词最美？", "wrongs": ["很多很慢", "飞来飞去"]}, {"why": "小狗叫的声音是“汪汪”。小猫才是“喵喵”，小鸡是“叽叽”，每种动物叫声都不一样哦。", "right": "汪汪", "title": "小狗怎么叫", "topic": "句子", "prompt": "“小狗____地叫起来。”填哪个词最合适？", "wrongs": ["喵喵", "叽叽"]}, {"why": "“解落三秋叶，能开二月花”——风能吹落秋天的叶子，也能吹开春天二月的花，本领真大。", "right": "能开二月花", "title": "《风》能做什么", "topic": "古诗", "prompt": "李峤《风》里“解落三秋叶，____”，风还能做什么？", "wrongs": ["能开三月花", "飞在青云端"]}, {"why": "《风》是唐朝诗人李峤写的。风过江能掀起大浪，进竹林能把竹子吹得歪歪斜斜。", "right": "李峤", "title": "《风》是谁写的", "topic": "古诗", "prompt": "“过江千尺浪，入竹万竿斜”这首《风》是谁写的？", "wrongs": ["李白", "杨万里"]}, {"why": "“松下问童子，言师采药去”——在松树下问小童，他说师父进山采药去了，没遇上。", "right": "采药去了", "title": "采药去哪了", "topic": "古诗", "prompt": "《寻隐者不遇》里问童子，师父去做什么了？", "wrongs": ["睡觉去了", "钓鱼去了"]}, {"why": "“只在此山中，云深不知处”——师父就在这座山里，可云雾太深，不知道具体在哪儿。这是贾岛写的。", "right": "云深不知处", "title": "师父在哪里", "topic": "古诗", "prompt": "《寻隐者不遇》里“只在此山中，____”，为什么找不到师父？", "wrongs": ["采药未曾归", "低头思故乡"]}, {"why": "“桃花潭水深千尺，不及汪伦送我情”——水再深，也比不上汪伦送别李白的情谊深。", "right": "不及汪伦送我情", "title": "汪伦送的情", "topic": "古诗", "prompt": "《赠汪伦》里“桃花潭水深千尺，____”，下一句是什么？", "wrongs": ["不及汪伦送我船", "低头思故乡"]}, {"why": "《赠汪伦》是唐朝李白写的，送给好朋友汪伦。诗里第一句就有他自己的名字呢。", "right": "李白", "title": "《赠汪伦》谁写的", "topic": "古诗", "prompt": "“李白乘舟将欲行”这首《赠汪伦》是谁写的？", "wrongs": ["汪伦", "杜甫"]}, {"why": "“一叫千门万户开”——大公鸡一打鸣，家家户户的门都打开了，天亮该起床啦。", "right": "万户开", "title": "大公鸡一叫", "topic": "古诗", "prompt": "唐寅《画鸡》里“一叫千门____”，大公鸡一叫怎么样？", "wrongs": ["万户关", "万家眠"]}, {"why": "“一去二三里，烟村四五家”——走出二三里路，看见薄雾里有四五户人家。这首诗藏着一到十的数字。", "right": "烟村四五家", "title": "一去二三里", "topic": "古诗", "prompt": "《山村咏怀》里“一去二三里，____”，下一句是什么？", "wrongs": ["亭台六七座", "八九十枝花"]}, {"why": "天黑了打开“电灯”，屋里就亮堂堂的。雨伞是挡雨的，扇子是热的时候扇风的。", "right": "电灯", "title": "天黑用什么", "topic": "理解", "prompt": "晚上屋里黑黑的，想看清东西要打开什么？", "wrongs": ["雨伞", "扇子"]}, {"why": "“红灯停，绿灯行”——绿灯亮了才可以走，红灯亮了要停下来等一等，这样最安全。", "right": "绿灯", "title": "过马路看灯", "topic": "理解", "prompt": "过马路的时候，看见什么颜色的灯才能走？", "wrongs": ["红灯", "黄灯"]}, {"why": "小蝌蚪慢慢长出四条腿、掉了尾巴，就变成会跳的“青蛙”啦。小鱼一直在水里游，不会变。", "right": "青蛙", "title": "小蝌蚪找谁", "topic": "理解", "prompt": "小蝌蚪黑黑的、有长尾巴，它长大以后会变成什么？", "wrongs": ["小鱼", "乌龟"]}, {"why": "春天暖和，小草发芽、花儿开放，到处绿绿的。下雪是冬天，叶子掉光是秋天的事哦。", "right": "草发芽、花开了", "title": "春天会怎样", "topic": "理解", "prompt": "暖暖的春天来了，树上和花园里会发生什么？", "wrongs": ["下大雪", "树叶都掉光"]}, {"why": "“长得高”是说“生长”，读 zhǎng；“长江”“长长的”才读 cháng。意思不一样，读音也就不一样啦。", "right": "zhǎng", "title": "长的两个音", "topic": "多音字", "prompt": "“他长得很高”里的“长”，读 zhǎng 还是 cháng 呢？", "wrongs": ["cháng", "两个都行"]}, {"why": "“银行”读 háng，跟行业、一行字一样；“行走”“不行”才读 xíng。", "right": "háng", "title": "行的两个音", "topic": "多音字", "prompt": "“银行”里的“行”，应该读哪个音？", "wrongs": ["xíng", "hén"]}, {"why": "“音乐”读 yuè；“快乐”“乐呵呵”才读 lè。看它表示什么意思来选音。", "right": "yuè", "title": "乐的两个音", "topic": "多音字", "prompt": "“音乐”里的“乐”，读 yuè 还是 lè？", "wrongs": ["lè", "yào"]}, {"why": "“睡觉”读 jiào；“觉得”“感觉”读 jué。睡觉的“觉”是名词，读 jiào。", "right": "jiào", "title": "觉的两个音", "topic": "多音字", "prompt": "“睡觉”里的“觉”，读哪个音才对？", "wrongs": ["jué", "jué儿"]}, {"why": "“因为”“为了”读 wèi；“成为”“以为”读 wéi。可以多读几遍记住它。", "right": "wèi", "title": "为的两个音", "topic": "多音字", "prompt": "“因为”里的“为”，读 wèi 还是 wéi？", "wrongs": ["wéi", "wèn"]}, {"why": "“种树”是“栽种”的动作，读 zhòng；“种子”“一种”读 zhǒng。", "right": "zhòng", "title": "种的两个音", "topic": "多音字", "prompt": "“种树”里的“种”，应该读哪个音？", "wrongs": ["zhǒng", "chóng"]}, {"why": "“难过”“困难”读 nán；“灾难”“难民”读 nàn。心里不舒服的“难过”读 nán。", "right": "nán", "title": "难的两个音", "topic": "多音字", "prompt": "“难过”里的“难”，读 nán 还是 nàn？", "wrongs": ["nàn", "lán"]}, {"why": "“首都”“都市”读 dū；“都来了”“全都”读 dōu。北京是首都，读 dū。", "right": "dū", "title": "都的两个音", "topic": "多音字", "prompt": "“首都北京”里的“都”，读哪个音？", "wrongs": ["dōu", "dòu"]}, {"why": "“头发”“理发”读 fà；“发现”“出发”读 fā。长在头上的“头发”读 fà。", "right": "fà", "title": "发的两个音", "topic": "多音字", "prompt": "“头发”里的“发”，读 fà 还是 fā？", "wrongs": ["fā", "fán"]}, {"why": "“朋”读 péng，音序就是它拼音的第一个字母大写 P。先找 P，再按后面的音节找。", "right": "P", "title": "音序查字法", "topic": "查字典", "prompt": "用音序查字法查“朋”字，要先翻到哪个大写字母？", "wrongs": ["B", "F"]}, {"why": "它们都和水有关，左边都是“氵”，所以都查三点水这个部首。", "right": "三点水（氵）", "title": "部首查字法", "topic": "查字典", "prompt": "“江、河、海”这三个字，都用哪个部首查字典？", "wrongs": ["工字旁", "可字旁"]}, {"why": "“火”按笔顺写是：点、撇、撇、捺，正好 4 画。可以边写边数。", "right": "4画", "title": "数一数笔画", "topic": "查字典", "prompt": "“火”这个字，一共有几画？", "wrongs": ["3画", "5画"]}, {"why": "它们头上都有“艹”，和植物有关，所以查草字头。", "right": "草字头（艹）", "title": "草字头查字典", "topic": "查字典", "prompt": "“花、草、苹”这些字，应该查哪个部首？", "wrongs": ["人字头", "宝盖头"]}, {"why": "它们都和树木有关，左边都带“木”，所以查木字旁。", "right": "木字旁（木）", "title": "木字旁查字典", "topic": "查字典", "prompt": "想查“松、林、树”，用哪个部首最合适？", "wrongs": ["公字旁", "寸字旁"]}, {"why": "“画”是 8 画。这是个常考的字，可以慢慢按笔顺写一遍数出来。", "right": "8画", "title": "“画”有几画", "topic": "查字典", "prompt": "“画”这个字，一共多少笔画？", "wrongs": ["7画", "9画"]}, {"why": "它们都和嘴巴的动作有关，左边都是“口”，所以查口字旁。", "right": "口字旁（口）", "title": "口字旁查字典", "topic": "查字典", "prompt": "“叫、吃、唱”这几个字，查哪个部首？", "wrongs": ["日字旁", "日字底"]}, {"why": "水很干净要用三点水的“清”；“青”是颜色（青草），“请”是请客。", "right": "清", "title": "清还是青", "topic": "形近字", "prompt": "“河水很___”，是清水的“清”还是青草的“青”？", "wrongs": ["青", "请"]}, {"why": "形状圆圆的用“圆”；“公园”的园是花园的园，“元”是元旦的元。", "right": "圆", "title": "园还是圆", "topic": "形近字", "prompt": "“圆圆的月亮”，用哪个“yuán”？", "wrongs": ["园", "元"]}, {"why": "“再见”表示又一次，用“再”；“在家”“在哪”表示位置，用“在”。", "right": "再", "title": "在还是再", "topic": "形近字", "prompt": "“明天___见”，是在家的“在”还是再见的“再”？", "wrongs": ["在", "存"]}, {"why": "“自己”用开口的“己”；“已经”用半口的“已”。多写几遍记住口张多大。", "right": "己", "title": "己还是已", "topic": "形近字", "prompt": "“我自___做”，应该用哪个字？", "wrongs": ["已", "巳"]}, {"why": "“周末”是一周的末尾，用上横长的“末”；“未来”的“未”上横短。", "right": "末", "title": "末还是未", "topic": "形近字", "prompt": "“周___休息”（每周最后），用哪个字？", "wrongs": ["未", "木"]}, {"why": "小动物“兔”右下有一点（像小尾巴）；“免”没有那一点，是免费的免。", "right": "兔", "title": "免还是兔", "topic": "形近字", "prompt": "“小白___爱吃萝卜”，填哪个字？", "wrongs": ["免", "色"]}, {"why": "和眼睛有关的字常用“目”字旁，比如睛、眼、睡。“日”是太阳。", "right": "目", "title": "日还是目", "topic": "形近字", "prompt": "“眼睛”的“睛”左边，是太阳的“日”还是眼睛的“目”？", "wrongs": ["日", "田"]}, {"why": "水的波浪用三点水的“波”；“山坡”用土字旁的“坡”，因为坡是土做的。", "right": "波", "title": "波还是坡", "topic": "形近字", "prompt": "“海上有大___浪”，用哪个字？", "wrongs": ["坡", "破"]}, {"why": "“体育”的体里面是“本”；“休息”的休里面是“木”。可以看中间不一样。", "right": "体", "title": "休还是体", "topic": "形近字", "prompt": "“上___课要做运动”，用哪个字？", "wrongs": ["休", "本"]}, {"why": "口干想喝水是“口渴”，用三点水（缺水）；“喝水”这个动作用口字旁。", "right": "渴", "title": "渴还是喝", "topic": "形近字", "prompt": "“口很___，想喝水”，用哪个字？", "wrongs": ["喝", "歇"]}, {"why": "“夜幕”像一块大布盖下来，下面是“巾”（布）；“羡慕”跟心情有关，下面是“心”。", "right": "幕", "title": "幕还是慕", "topic": "形近字", "prompt": "“夜___降临”（天黑下来），用哪个字？", "wrongs": ["慕", "墓"]}, {"why": "太阳又红又热，常说“火红的太阳”。雪白、冰凉跟太阳的感觉不搭哦。", "right": "火红", "title": "什么样的太阳", "topic": "词语搭配", "prompt": "“___的太阳”，下面哪个搭配最合适？", "wrongs": ["雪白", "冰凉"]}, {"why": "图画是画出来的，所以是“画图画”。唱歌、吃饭才配唱和吃。", "right": "画", "title": "动词配名词", "topic": "词语搭配", "prompt": "“___图画”，下面哪个动词配得对？", "wrongs": ["唱", "吃"]}, {"why": "月亮可以是弯弯的（月牙）；太阳是圆的，黑板是方方的。", "right": "月亮", "title": "弯弯的什么", "topic": "词语搭配", "prompt": "“弯弯的___”，填什么最好？", "wrongs": ["太阳", "黑板"]}, {"why": "“一心一意”是说专心做一件事，不三心二意。", "right": "意", "title": "补成语：一心一___", "topic": "成语入门", "prompt": "成语“一心一___”，最后一个字是什么？", "wrongs": ["用", "力"]}, {"why": "“四面八方”指各个方向、到处都是。", "right": "方", "title": "补成语：四面八___", "topic": "成语入门", "prompt": "成语“四面八___”，缺的字是？", "wrongs": ["角", "边"]}, {"why": "“五颜六色”形容颜色又多又漂亮，比如花园里五颜六色的花。", "right": "色", "title": "补成语：五颜六___", "topic": "成语入门", "prompt": "形容颜色很多，“五颜六___”填什么？", "wrongs": ["彩", "光"]}, {"why": "“守株待兔”讲一个人傻等兔子撞树，比喻不肯努力、只想碰运气。", "right": "兔", "title": "补成语：守株待___", "topic": "成语入门", "prompt": "寓言故事“守株待___”，最后一个字是？", "wrongs": ["鱼", "鸟"]}, {"why": "“亡羊补牢”是说羊丢了赶紧修羊圈，比喻出了问题及时补救还不晚。", "right": "牢", "title": "补成语：亡羊补___", "topic": "成语入门", "prompt": "成语“亡羊补___”，缺的字是什么？", "wrongs": ["门", "圈"]}, {"why": "小动物常用“只”，比如一只小鸟、一只猫。“条”配鱼，“棵”配树。", "right": "只", "title": "量词用对了吗", "topic": "词语搭配", "prompt": "“一___小鸟”，用哪个量词最对？", "wrongs": ["条", "棵"]}, {"why": "长长弯弯的东西用“条”，比如一条小河、一条路。山用“座”，云用“朵”。", "right": "小河", "title": "一条什么", "topic": "词语搭配", "prompt": "“一条___”，下面哪个最合适？", "wrongs": ["大山", "云朵"]}, {"why": "“又大又圆”都是夸西瓜的好词。“又大又小”自相矛盾，不通顺。", "right": "圆", "title": "补成语：又大又___", "topic": "成语入门", "prompt": "形容西瓜很好，“又大又___”可以填什么？", "wrongs": ["酸", "小"]}, {"why": "“高兴”和“快乐”都表示心情好；伤心、生气是相反的心情。", "right": "快乐", "title": "高兴的近义词", "topic": "近义词", "prompt": "“高兴”和下面哪个词意思最接近？", "wrongs": ["伤心", "生气"]}, {"why": "“美丽”和“漂亮”都是夸好看；难看、丑陋是反义。", "right": "漂亮", "title": "美丽的近义词", "topic": "近义词", "prompt": "“美丽”跟哪个词意思差不多？", "wrongs": ["难看", "丑陋"]}, {"why": "“认真”是做事仔细不出错；它的反义是“马虎”（粗心大意）。", "right": "马虎", "title": "认真的反义词", "topic": "反义词", "prompt": "“认真”的反义词是哪个？", "wrongs": ["仔细", "专心"]}, {"why": "“寒冷”很冷，反义是很热的“炎热”。冰凉跟寒冷意思相近哦。", "right": "炎热", "title": "寒冷的反义词", "topic": "反义词", "prompt": "“寒冷”的反义词是？", "wrongs": ["冰凉", "凉快"]}, {"why": "“著名”就是很有名、大家都知道，所以近义词是“有名”。", "right": "有名", "title": "著名的近义词", "topic": "近义词", "prompt": "“著名”和哪个词最像？", "wrongs": ["普通", "陌生"]}, {"why": "“增加”是变多，反义是变少的“减少”。", "right": "减少", "title": "增加的反义词", "topic": "反义词", "prompt": "“增加”的反义词是哪个？", "wrongs": ["很多", "加上"]}, {"why": "“连忙”是很快地、马上去做，所以近义词是“赶紧”。", "right": "赶紧", "title": "连忙的近义词", "topic": "近义词", "prompt": "“他连忙跑过去”，“连忙”跟哪个词意思像？", "wrongs": ["慢慢", "故意"]}, {"why": "“安静”没声音；反义是又吵又闹的“热闹”。平静和安静意思相近。", "right": "热闹", "title": "安静的反义词", "topic": "反义词", "prompt": "“安静”的反义词是？", "wrongs": ["平静", "安全"]}, {"why": "“高大”和“高耸”都说又高又大；矮小是相反的意思。", "right": "高耸", "title": "高大的近义词", "topic": "近义词", "prompt": "“高大的树”，“高大”跟哪个词意思接近？", "wrongs": ["矮小", "细长"]}, {"why": "“骄傲”是看不起别人；反义是不夸自己、肯学习的“谦虚”。", "right": "谦虚", "title": "骄傲的反义词", "topic": "反义词", "prompt": "“骄傲”（自以为很厉害）的反义词是？", "wrongs": ["自满", "得意"]}, {"why": "下雨是原因，没去是结果，用“因为…所以”把原因和结果连起来。", "right": "因为…所以", "title": "因为…所以", "topic": "关联词", "prompt": "“___下雨了，___我们没去公园。”填哪一组词？", "wrongs": ["虽然…但是", "如果…就"]}, {"why": "天冷本该不想跑，他偏跑了，前后有转折，用“虽然…但是”。", "right": "虽然…但是", "title": "虽然…但是", "topic": "关联词", "prompt": "“___天气很冷，___他还是坚持跑步。”填哪一组？", "wrongs": ["因为…所以", "只要…就"]}, {"why": "“明天天晴”还没发生，是一种假设，用“如果…就”。", "right": "如果…就", "title": "如果…就", "topic": "关联词", "prompt": "“___明天天晴，我们___去爬山。”填哪一组？", "wrongs": ["因为…所以", "虽然…但是"]}, {"why": "“只要…就”表示有了这个条件，结果一定会出现。", "right": "只要…就", "title": "只要…就", "topic": "关联词", "prompt": "“___你认真练，___能写好字。”填哪一组？", "wrongs": ["虽然…但是", "不但…而且"]}, {"why": "前面好，后面又更进一步好，用“不但…而且”表示更进一层。", "right": "不但…而且", "title": "不但…而且", "topic": "关联词", "prompt": "“她___学习好，___很爱帮助人。”填哪组？", "wrongs": ["如果…就", "因为…所以"]}, {"why": "前面是原因（生病），后面是结果（没来），所以要用“所以”。", "right": "所以", "title": "选对因果", "topic": "关联词", "prompt": "“因为他生病了，___没来上学。”横线上填什么？", "wrongs": ["但是", "如果"]}, {"why": "题难，本以为做不出，却做出来了，前后是转折，用“但是”。", "right": "但是", "title": "转折要用谁", "topic": "关联词", "prompt": "“这道题很难，___我做出来了。”横线上填什么最好？", "wrongs": ["所以", "因为"]}, {"why": "扩句就是加上一些词让句子更具体，比如加“可爱的”“在天上”，意思更丰富。", "right": "可爱的小鸟在天上飞。", "title": "给句子加词", "topic": "扩句", "prompt": "把“小鸟飞”扩得更生动，下面哪句最好？", "wrongs": ["小鸟。", "飞。"]}, {"why": "缩句要留下“谁干什么”，去掉修饰的词。这里就是“蝴蝶飞舞”。", "right": "蝴蝶飞舞。", "title": "把句子变短", "topic": "缩句", "prompt": "“美丽的蝴蝶在花丛中飞舞。”缩成最简单的句子是？", "wrongs": ["美丽的蝴蝶。", "在花丛中。"]}, {"why": "比喻句把一样东西说成像另一样，常有“像”字。月亮像小船就是比喻。", "right": "弯弯的月亮像小船。", "title": "认一认比喻句", "topic": "比喻", "prompt": "下面哪一句是比喻句（把一样东西说成另一样）？", "wrongs": ["月亮在天上。", "今晚有月亮。"]}, {"why": "拟人句让东西像人一样会动作、有心情。小草会“偷偷探头”，就是拟人。", "right": "小草偷偷地探出头来。", "title": "认一认拟人句", "topic": "拟人", "prompt": "下面哪一句把东西当成人来写（拟人）？", "wrongs": ["小草是绿色的。", "草地上有小草。"]}, {"why": "这是一句问话，句末要用问号“？”。", "right": "问号（？）", "title": "问句用什么号", "topic": "标点", "prompt": "“你今天去上学吗”，句末应该用什么标点？", "wrongs": ["句号（。）", "感叹号（！）"]}, {"why": "表示开心、惊讶等强烈感情时，句末用感叹号“！”。", "right": "感叹号（！）", "title": "感叹用什么号", "topic": "标点", "prompt": "“这朵花真漂亮”，要表示很惊喜，句末用什么号？", "wrongs": ["问号（？）", "逗号（，）"]}, {"why": "一句话还没说完、中间要停一下，用逗号“，”。", "right": "逗号（，）", "title": "句中停顿用逗号", "topic": "标点", "prompt": "“吃完饭___我们去散步。”中间该用什么标点？", "wrongs": ["句号（。）", "问号（？）"]}, {"why": "雪花又白又轻，像鹅毛一样飘下来；石头、泥巴又重又脏，不像雪花。", "right": "鹅毛", "title": "比作什么", "topic": "比喻", "prompt": "“雪花像___一样落下来。”填哪个比喻最美？", "wrongs": ["石头", "泥巴"]}, {"why": "缩句保留“谁做了什么”，所以是“妈妈做了饭菜”，去掉修饰词。", "right": "妈妈做了饭菜。", "title": "留住主干", "topic": "缩句", "prompt": "“勤劳的妈妈做了一桌香喷喷的饭菜。”缩句是？", "wrongs": ["勤劳的妈妈。", "香喷喷的饭菜。"]}, {"why": "在“某某说”后面、引用别人的话之前，要用冒号“：”再加引号。", "right": "冒号（：）", "title": "说话用冒号", "topic": "标点", "prompt": "“老师说___‘大家好。’”横线上该用什么标点？", "wrongs": ["句号（。）", "问号（？）"]}, {"why": "“微笑”是人才会做的事，让花会微笑，就把花写成人了，这是拟人。", "right": "花儿对着我们微笑。", "title": "让花会笑", "topic": "拟人", "prompt": "想写一句拟人句，下面哪句把花当成了人？", "wrongs": ["花儿是红色的。", "花园里有很多花。"]}, {"why": "句子说“天要下雨”“忙着搬粮食回家”，所以蚂蚁是在下雨前搬粮食。", "right": "下雨前忙着搬粮食", "title": "读一读：小蚂蚁", "topic": "段落理解", "prompt": "“天要下雨了，蚂蚁们忙着把粮食搬回家。”这段告诉我们蚂蚁在干什么？", "wrongs": ["在睡觉", "在玩水"]}, {"why": "段子开头就说“秋天到了”，树叶黄了、飘落也都是秋天的样子。", "right": "秋天", "title": "读一读：秋天到", "topic": "段落理解", "prompt": "“秋天到了，树叶黄了，一片片飘落下来。”这段写的是哪个季节？", "wrongs": ["春天", "夏天"]}, {"why": "“天不亮就去干活”说明爷爷起得早、干得多，所以是夸他勤劳。", "right": "很勤劳", "title": "读一读：勤劳的爷爷", "topic": "段落理解", "prompt": "“爷爷每天天不亮就去地里干活。”这句夸爷爷怎么样？", "wrongs": ["很懒", "爱睡懒觉"]}, {"why": "把好吃的分给别人，说明小明大方、懂得分享。", "right": "懂得分享", "title": "读一读：小明的礼物", "topic": "段落理解", "prompt": "“小明把自己的零食分给了同桌。”这件事说明小明怎么样？", "wrongs": ["很小气", "不爱吃零食"]}, {"why": "句子最后说“出现了一道彩虹”，所以写的是雨后的彩虹。", "right": "彩虹", "title": "读一读：雨后", "topic": "段落理解", "prompt": "“雨停了，天边出现了一道彩虹。”这段最后写到了什么？", "wrongs": ["下雪", "打雷"]}, {"why": "“轻轻放回原位”说明大家很小心、守规矩，爱护图书。", "right": "爱护图书、守规矩", "title": "读一读：图书角", "topic": "段落理解", "prompt": "“同学们看完书，都把书轻轻放回了原来的位置。”这说明大家怎么样？", "wrongs": ["乱扔书", "不爱看书"]}, {"why": "《登鹳雀楼》是王之涣写的，原句是“白日依山尽，黄河入海流”。", "right": "黄河入海流", "title": "登鹳雀楼·下一句", "topic": "古诗", "prompt": "“白日依山尽，”的下一句是什么？", "wrongs": ["黄河绕山流", "长江入海流"]}, {"why": "《望庐山瀑布》是唐代大诗人李白写的，他特别爱写又大又美的山水。", "right": "李白", "title": "望庐山瀑布·作者", "topic": "古诗", "prompt": "“飞流直下三千尺”出自《望庐山瀑布》，作者是谁？", "wrongs": ["杜甫", "王维"]}, {"why": "“穹庐”就是草原上的大帐篷，诗里说天像帐篷一样罩着大草原。", "right": "大帐篷（蒙古包）", "title": "敕勒歌·天空像什么", "topic": "古诗", "prompt": "《敕勒歌》里“天似穹庐”，把天空比作了什么？", "wrongs": ["大海", "大山"]}, {"why": "苏轼是宋代有名的文学家，《赠刘景文》就是他写给好朋友的诗。", "right": "宋代", "title": "赠刘景文·作者朝代", "topic": "古诗", "prompt": "《赠刘景文》的作者苏轼，是哪个朝代的人？", "wrongs": ["唐代", "汉代"]}, {"why": "原句是“一年好景君须记，最是橙黄橘绿时”，说初冬橙黄橘绿的时候最美。", "right": "最是橙黄橘绿时", "title": "赠刘景文·名句", "topic": "古诗", "prompt": "《赠刘景文》里“一年好景君须记”的下一句是？", "wrongs": ["最是花红柳绿时", "最是冰天雪地时"]}, {"why": "《夜书所见》是南宋诗人叶绍翁写的，写他在秋夜里看到的景象和思乡之情。", "right": "叶绍翁", "title": "夜书所见·作者", "topic": "古诗", "prompt": "“萧萧梧叶送寒声”出自《夜书所见》，作者是谁？", "wrongs": ["李白", "王之涣"]}, {"why": "“促织”就是蟋蟀（蛐蛐），诗里写小朋友夜里打着灯笼去捉蟋蟀，很有趣。", "right": "蟋蟀", "title": "夜书所见·捉什么", "topic": "古诗", "prompt": "《夜书所见》里“知有儿童挑促织”，小朋友在捉什么小虫？", "wrongs": ["蝴蝶", "萤火虫"]}, {"why": "《望天门山》也是李白写的，写长江边天门山的壮丽景色。", "right": "李白", "title": "望天门山·作者", "topic": "古诗", "prompt": "“两岸青山相对出”出自《望天门山》，是谁写的？", "wrongs": ["苏轼", "叶绍翁"]}, {"why": "这首夸西湖的诗是宋代苏轼写的，他当时正在杭州做官。", "right": "苏轼", "title": "饮湖上初晴后雨·作者", "topic": "古诗", "prompt": "“水光潋滟晴方好”出自《饮湖上初晴后雨》，作者是谁？", "wrongs": ["李白", "杜甫"]}, {"why": "“欲把西湖比西子，淡妆浓抹总相宜”，把西湖比作美人西施，怎么打扮都好看。", "right": "西子（西施）", "title": "饮湖上·把西湖比作谁", "topic": "古诗", "prompt": "《饮湖上初晴后雨》把美丽的西湖比作了哪位古代美人？", "wrongs": ["嫦娥", "织女"]}, {"why": "这首杨万里的诗写的是夏天西湖的荷花，太阳一照，荷花格外红。", "right": "荷花", "title": "晓出净慈寺·写什么花", "topic": "古诗", "prompt": "《晓出净慈寺送林子方》里“映日荷花别样红”，写的是什么花？", "wrongs": ["桃花", "梅花"]}, {"why": "原句是“接天莲叶无穷碧，映日荷花别样红”，写满湖荷叶碧绿、荷花红艳。", "right": "映日荷花别样红", "title": "晓出净慈寺·名句", "topic": "古诗", "prompt": "“接天莲叶无穷碧”的下一句是什么？", "wrongs": ["映日桃花别样红", "迎风杨柳别样青"]}, {"why": "原句是“两个黄鹂鸣翠柳，一行白鹭上青天”，黄、绿、白、青，颜色特别美。", "right": "一行白鹭上青天", "title": "绝句·两个黄鹂", "topic": "古诗", "prompt": "杜甫《绝句》里“两个黄鹂鸣翠柳”的下一句是？", "wrongs": ["一群大雁向南飞", "一片白云飘过来"]}, {"why": "杜甫是唐代的大诗人，和李白齐名，人们叫他“诗圣”。", "right": "唐代", "title": "绝句·作者朝代", "topic": "古诗", "prompt": "写“两个黄鹂鸣翠柳”的杜甫，是哪个朝代的诗人？", "wrongs": ["宋代", "清代"]}, {"why": "“瓮”是口小肚大的大缸。小朋友掉进装满水的瓮里，司马光拿石头把瓮砸破救人。", "right": "瓮（大水缸）", "title": "司马光·砸的是什么", "topic": "文言文", "prompt": "《司马光》里“光持石击瓮破之”，司马光砸破的是什么？", "wrongs": ["一扇门", "一块大石头"]}, {"why": "“众皆弃去”是说大家都丢下同伴跑掉了，只有司马光想办法救人，很机智勇敢。", "right": "都吓得跑开了", "title": "司马光·别人怎么做", "topic": "文言文", "prompt": "《司马光》里“众皆弃去”是说其他小朋友怎么了？", "wrongs": ["都笑起来了", "都跳进水里"]}, {"why": "“株”就是树桩。兔子撞树桩死了一次，农夫就傻等下一只，结果再也等不到。", "right": "树桩（株）", "title": "守株待兔·守在哪", "topic": "文言文", "prompt": "《守株待兔》里那个农夫，整天守在什么旁边等兔子？", "wrongs": ["河边", "田里的稻草人"]}, {"why": "农夫不种田只等兔子，最后什么都没有。故事告诉我们：好运不会天天有，要靠自己努力。", "right": "不能只靠运气、要靠努力", "title": "守株待兔·讲的道理", "topic": "文言文", "prompt": "《守株待兔》这个故事是想告诉我们什么？", "wrongs": ["兔子很好吃", "种田没有用"]}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
